#!/usr/bin/env python3
"""Independent numerical reconstruction of optional Q4 evidence and feature/prediction traces."""
import os
os.environ['OPENBLAS_NUM_THREADS']='1'
import argparse,json,gzip,hashlib
from pathlib import Path
import numpy as np,pandas as pd
from scipy.stats import spearmanr
from sklearn.metrics import f1_score,accuracy_score,mean_absolute_error,r2_score
from sklearn.ensemble import ExtraTreesRegressor

def scores(y,p,t):
    if t=='coord':
        ff=f1_score(y,p,labels=[4,5,6],average=None,zero_division=0)
        return {'accuracy':accuracy_score(y,p),'macro_f1':float(ff.mean()),**{f'f1_{i}':v for i,v in zip([4,5,6],ff)}}
    return {'mae':mean_absolute_error(y,p),'r2':r2_score(y,p)}
def loss(y,p,t):
    if t!='coord':return np.mean(abs(y-p))
    f=[]
    for k in [4,5,6]:
        den=np.sum(y==k)+np.sum(p==k);f.append(2*np.sum((y==k)&(p==k))/den if den else 0.)
    return 1-np.mean(f)
def multiscale(X,E):
    features=[];defs=[]
    for width in (10,20,50):
        for start in range(0,100,width):
            local=np.linspace(-1,1,width)
            coeff=np.linalg.lstsq(np.column_stack([np.ones(width),local,local**2]),X[:,start:start+width].T,rcond=None)[0].T
            features.append(coeff)
            for deg in range(3):defs.append(dict(feature=len(defs),kind=f'degree_{deg}',width_points=width,start_eV=float(E[start]),end_eV=float(E[start+width-1])))
    return np.concatenate(features,axis=1),defs

def main():
    pp=argparse.ArgumentParser();pp.add_argument('--inputs',type=Path,required=True);pp.add_argument('--answer',type=Path,required=True);pp.add_argument('--packaged',type=Path);pp.add_argument('--output',type=Path,required=True);a=pp.parse_args();o=a.answer
    design=json.loads((o/'design.json').read_text());evidence=json.loads((o/'evidence.json').read_text());defs=json.loads((o/'feature_definitions.json').read_text());loc=json.loads((o/'localization.json').read_text());families=pd.read_csv(o/'shape_families.csv');parts=pd.read_csv(o/'partitions.csv');pred=pd.read_csv(o/'predictions.csv');pairs=pd.read_csv(o/'comparisons.csv');counts=pd.read_csv(o/'class_counts.csv');conf=pd.read_csv(o/'confusion.csv');runs={r['run_id']:r for r in design['runs']};raw={};out={'status':'pass','reconstruction':{},'warnings':[]}
    fields={'coord':'coordination','md':'avg_nn_dists','bader':'bader'}
    for el in ['Ti','V','Cr','Mn','Fe','Co','Ni','Cu']:
        with gzip.open(a.inputs/f'{el}.jsonl.gz','rt') as f: rr=[json.loads(x) for x in f]
        assert [r['source_row'] for r in rr]==list(range(len(rr)))
        raw[el]=rr
        X=np.array([r['mu'] for r in rr]);E=np.array(rr[0]['E']);Z,dd=multiscale(X,E)
        assert dd==defs[el+'_multiscale'];assert Z.shape==(len(rr),51)
        assert defs[el+'_pointwise']==[dict(feature=i,kind='absorption',start_eV=float(ee),end_eV=float(ee)) for i,ee in enumerate(E)]
    # Cohort coverage and training-only constants for every run.
    for cc in evidence['coverage']:
        rr=raw[cc['element']];yy=np.array([np.nan if r[fields[cc['target']]] is None else r[fields[cc['target']]] for r in rr]);known=np.array([bool(r['metadata'].get('id')) for r in rr]);X=np.array([r['mu'] for r in rr]);EE=np.array([r['E'] for r in rr]);valid=np.isfinite(yy)&np.isfinite(X).all(1)&np.isfinite(EE).all(1)&(X.max(1)>0)
        if cc['target']=='coord':valid &= np.isin(yy,[4,5,6])
        if cc['target']=='md':valid &= yy>0
        assert int(valid.sum())==cc['valid_target_records'];assert int((valid&known).sum())==cc['identified_valid_records']
        assert len({r['metadata']['id'] for r,v,k in zip(rr,valid,known) if v and k})==cc['identified_materials']
        assert np.isclose(np.mean(yy[valid&known]),cc['identified_target_mean']);assert np.isclose(np.mean(yy[valid&~known]),cc['unidentified_target_mean'])
    for bb in evidence['baselines']:
        run=runs[bb['run_id']]; rr=raw[run['element']];pa=parts[parts.run_id==run['run_id']];train=pa[pa.role=='train'].source_row.to_numpy();test=pa[pa.role=='test'].source_row.to_numpy();yt=np.array([rr[i][fields[run['target']]] for i in train]);yy=np.array([rr[i][fields[run['target']]] for i in test]);base=np.bincount(yt.astype(int)).argmax() if run['target']=='coord' else np.median(yt)
        assert base==bb['training_constant']
        for k,v in scores(yy,np.full(len(yy),base),run['target']).items():assert np.isclose(v,bb['metrics'][k],atol=1e-12)
        if run['target']=='coord':
            for role in ['train','validation','test']:
                iy=pa[pa.role==role].source_row;vv=np.array([rr[i]['coordination'] for i in iy]);ct=counts[(counts.run_id==run['run_id'])&(counts.role==role)]
                for k in [4,5,6]:assert sum(vv==k)==ct[ct.coordination==k]['count'].item()
            ppred=pred[pred.run_id==run['run_id']].set_index('source_row').loc[test].y_pred.to_numpy()
            for ka in [4,5,6]:
                for kb in [4,5,6]:assert sum((yy==ka)&(ppred==kb))==conf[(conf.run_id==run['run_id'])&(conf.true_coordination==ka)&(conf.predicted_coordination==kb)]['count'].item()
    out['reconstruction']['coverage_and_baselines']=len(evidence['baselines'])
    # All 48 paired material-bootstrap summaries, using an independent classwise loss implementation.
    for pair in pairs.to_dict('records'):
        rr=raw[pair['element']];ra=next(r for r in runs.values() if r['comparison_id']==pair['comparison_id'] and r['condition']==pair['first']);rb=next(r for r in runs.values() if r['comparison_id']==pair['comparison_id'] and r['condition']==pair['second']);pa=pred[pred.run_id==ra['run_id']].sort_values('source_row');pb=pred[pred.run_id==rb['run_id']].sort_values('source_row');assert np.array_equal(pa.source_row,pb.source_row);ids=pa.source_row.to_numpy();yy=np.array([rr[i][fields[pair['target']]] for i in ids]);gg=np.array([rr[i]['metadata']['id'] for i in ids]);member=[np.flatnonzero(gg==g) for g in np.unique(gg)];rng=np.random.default_rng(101);delta=[]
        p0=pa.y_pred.to_numpy();p1=pb.y_pred.to_numpy()
        for _ in range(250):
            ix=np.concatenate([member[j] for j in rng.integers(len(member),size=len(member))]);delta.append(loss(yy[ix],p0[ix],pair['target'])-loss(yy[ix],p1[ix],pair['target']))
        for k,v in [('gain',loss(yy,p0,pair['target'])-loss(yy,p1,pair['target'])),('low',np.quantile(delta,.025)),('high',np.quantile(delta,.975))]:assert np.isclose(v,pair[k],atol=1e-12)
    out['reconstruction']['paired_bootstrap_comparisons']=len(pairs)
    for st in evidence['localization_stability']:
        la=np.array([x['loss_increase'] for x in loc if x['run_id']==st['first_run']]);lb=np.array([x['loss_increase'] for x in loc if x['run_id']==st['second_run']]);rho=spearmanr(la,lb).statistic
        assert np.isclose(rho,st['spearman'],atol=1e-12) if st['spearman'] is not None else not np.isfinite(rho)
        assert bool(np.argmax(la)==np.argmax(lb))==st['top_region_same']
    out['reconstruction']['rank_stability_contrasts']=len(evidence['localization_stability'])
    # Trace one complete Bader prediction vector and all associated perturbations in each representation.
    traces=[]
    rr=raw['Ti'];X=np.array([r['mu'] for r in rr]);E=np.array(rr[0]['E']);y=np.array([np.nan if r['bader'] is None else r['bader'] for r in rr])
    for condition in ['pointwise','multiscale']:
        run=next(r for r in runs.values() if r['element']=='Ti' and r['target']=='bader' and r['repeat']==0 and r['condition']==condition);rid=run['run_id'];pa=parts[parts.run_id==rid];train=pa[pa.role=='train'].source_row.to_numpy();test=pa[pa.role=='test'].source_row.to_numpy();Z,dd=multiscale(X,E) if condition=='multiscale' else (X,defs['Ti_pointwise'])
        model=ExtraTreesRegressor(n_estimators=80,min_samples_leaf=run['selected_min_samples_leaf'],max_features=.8,random_state=113,n_jobs=2).fit(Z[train],y[train]);yp=model.predict(Z[test]);expected=pred[pred.run_id==rid].set_index('source_row').loc[test].y_pred.to_numpy();difference=float(np.max(abs(yp-expected)));assert np.allclose(yp,expected,atol=1e-12,rtol=1e-12),(condition,difference)
        rng=np.random.default_rng(113);base=loss(y[test],yp,'bader');edges=np.linspace(E.min(),E.max(),6);center=np.array([(x['start_eV']+x['end_eV'])/2 for x in dd]);max_diff=0.
        for b in range(5):
            ii=np.flatnonzero((center>=edges[b])&((center<edges[b+1]) if b<4 else (center<=edges[b+1])));values=[]
            for _ in range(3):
                z=Z[test].copy();perm=rng.permutation(len(test));z[:,ii]=z[perm[:,None],ii];values.append(loss(y[test],model.predict(z),'bader')-base)
            ll=next(x for x in loc if x['run_id']==rid and x['region']==b);assert list(ii)==ll['features'];assert np.isclose(np.mean(values),ll['loss_increase'],atol=1e-12);assert np.isclose(np.std(values),ll['permutation_sd'],atol=1e-12);max_diff=max(max_diff,abs(np.mean(values)-ll['loss_increase']))
        if condition=='multiscale':
            for degree in range(3):
                ii=[i for i,x in enumerate(dd) if x['kind']==f'degree_{degree}'];z=Z[test].copy();perm=rng.permutation(len(test));z[:,ii]=z[perm[:,None],ii];value=loss(y[test],model.predict(z),'bader')-base;assert np.isclose(value,families[(families.run_id==rid)&(families.degree==degree)].loss_increase.item(),atol=1e-12)
        traces.append(dict(run_id=rid,source_row=int(test[0]),n_features=Z.shape[1],first_feature_vector=Z[test[0]].tolist(),prediction=float(yp[0]),maximum_prediction_difference=difference,maximum_localization_difference=max_diff))
    out['traces']=traces
    out['review_findings']={'midpoint_bin_support':'50-point coefficients represent half the energy range although assigned by midpoint to a single fifth. The representation map is correct, but region prose needs this distinction.','bootstrap':'250 paired test-group resamples produce approximate conditional percentile intervals; two overlapping heldouts are sensitivity, not independent replication.','permutation':'Three row permutations per band and one per degree family quantify model sensitivity, not material-population uncertainty of an attribution.'}
    if a.packaged and (a.packaged/'predictions.csv').exists():
        comparison={}
        for filename,keys in [('predictions.csv',['run_id','source_row']),('partitions.csv',['run_id','source_row']),('metrics.csv',['run_id','metric']),('comparisons.csv',['comparison_id'])]:
            aa=pd.read_csv(o/filename).sort_values(keys).reset_index(drop=True);bb=pd.read_csv(a.packaged/filename).sort_values(keys).reset_index(drop=True);assert list(aa.columns)==list(bb.columns) and aa.shape==bb.shape;maxdiff=0.
            for col in aa:
                if pd.api.types.is_numeric_dtype(aa[col]):
                    assert np.allclose(aa[col],bb[col],atol=1e-12,rtol=1e-12,equal_nan=True);maxdiff=max(maxdiff,float(np.max(np.abs(aa[col]-bb[col]))))
                else:assert aa[col].equals(bb[col])
            comparison[filename]={'rows':len(aa),'max_numeric_difference':maxdiff}
        out['packaged_comparison']=comparison
    else:out['packaged_comparison']={'status':'not_yet_available'}
    a.output.write_text(json.dumps(out,indent=2));print(json.dumps({k:v for k,v in out.items() if k!='traces'},indent=2))
